-- iŘemeslo – stránky profesí (/remeslnici/<slug>), upravitelné a rozšiřitelné v administraci /ssh/profese.
--
-- Výchozích 23 profesí (texty v db/seed/professions.py). Provozovatel může texty měnit, profese skrýt
-- nebo přidat vlastní. Veřejně se čtou jen zveřejněné (RLS).

create table if not exists public.professions (
  slug text primary key check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and length(slug) between 2 and 60),
  name text not null check (length(name) between 2 and 80),
  category text not null check (category in ('malovani', 'fasady', 'cisteni', 'renovace', 'strechy', 'podlahy', 'obklady', 'zednicke', 'instalace', 'elektro', 'tesarske', 'zahrada', 'uklid', 'jine')),
  meta_title text not null check (length(meta_title) between 10 and 90),
  meta_description text not null check (length(meta_description) between 50 and 200),
  intro text not null check (length(intro) between 50 and 2000),
  services text[] not null default '{}' check (cardinality(services) <= 20),
  price_factors text[] not null default '{}' check (cardinality(price_factors) <= 20),
  tip text check (length(tip) <= 600),
  faq jsonb not null default '[]'::jsonb check (jsonb_typeof(faq) = 'array' and jsonb_array_length(faq) <= 10),
  published boolean not null default true,
  sort int not null default 100,
  updated_at timestamptz not null default now()
);
alter table public.professions enable row level security;
drop policy if exists professions_read on public.professions;
create policy professions_read on public.professions for select using (published);
grant select on public.professions to anon, authenticated;

insert into public.professions (slug, name, category, meta_title, meta_description, intro, services, price_factors, tip, faq, sort)
select slug, name, category, meta_title, meta_description, intro, services, price_factors, tip, faq, sort
from jsonb_to_recordset($seed$[{"slug": "instalater", "name": "Instalatér", "category": "instalace", "meta_title": "Instalatér – poptávka zdarma", "meta_description": "Hledáte instalatéra? Zadejte poptávku zdarma: rozvody vody a odpadů, koupelny, baterie, WC i opravy úniků. Ozvou se řemeslníci s ověřeným IČO.", "intro": "Instalatér se postará o všechno, co souvisí s vodou a odpady – od kapajícího kohoutku po kompletní rozvody v novostavbě. Popište v poptávce, co je potřeba, jak je byt nebo dům starý a jestli jde o havárii, nebo plánovanou práci. Čím přesnější popis a fotky stavu, tím rychleji dostanete reálnou nabídku.", "services": ["Nové rozvody vody a odpadů při rekonstrukci", "Montáž a výměna baterií, umyvadel, WC a sprchových koutů", "Opravy úniků vody, ucpaných odpadů a protékajících splachovačů", "Připojení pračky, myčky a ohřívače vody", "Výměna stoupaček v bytových domech", "Tlakové zkoušky a předání nových rozvodů"], "price_factors": ["Rozsah – výměna jednoho prvku, nebo celé rozvody", "Materiál rozvodů (plast, měď, vícevrstvé potrubí) a zařizovací předměty", "Přístupnost – rozvody ve zdi, pod obkladem nebo v šachtě", "Nutnost bourání a následných zednických prací", "Spěch: havarijní výjezd mimo pracovní dobu"], "tip": "Při havárii nejdřív zavřete hlavní uzávěr vody. Do poptávky napište, kde uzávěr je a jestli funguje – instalatér tak hned ví, s čím počítat.", "faq": [{"q": "Kdo dodá materiál?", "a": "Domluvte se předem. Někteří instalatéři materiál nakupují sami, jiní pracují s vaším. V nabídce chtějte materiál a práci zvlášť."}, {"q": "Mám chtít záruku?", "a": "Ano. Na práci i materiál chtějte záruku písemně, ideálně ve smlouvě o dílo nebo na faktuře."}], "sort": 1}, {"slug": "topenar", "name": "Topenář", "category": "instalace", "meta_title": "Topenář – výměna kotle a topení, poptávka zdarma", "meta_description": "Topenář na výměnu kotle, radiátorů nebo celé otopné soustavy. Zadejte poptávku zdarma a bez registrace, ozvou se firmy s ověřeným IČO.", "intro": "Topenář navrhne, namontuje a seřídí vytápění – kotel, radiátory, podlahové topení i rozvody. Kvalitně zapojené a vyregulované topení šetří peníze každou zimu. V poptávce uveďte typ vytápění, velikost domu nebo bytu a co chcete změnit; pokud máte projekt nebo výpočet tepelných ztrát, zmiňte ho.", "services": ["Výměna plynového kotle za kondenzační", "Montáž a výměna radiátorů a termostatických hlavic", "Podlahové vytápění a jeho regulace", "Nové rozvody topení při rekonstrukci", "Proplach a odvzdušnění otopné soustavy", "Napojení tepelného čerpadla nebo krbových kamen s výměníkem na soustavu"], "price_factors": ["Typ zdroje tepla a jeho výkon", "Počet radiátorů a délka rozvodů", "Stav stávající soustavy – zanesení, netěsnosti, staré potrubí", "Odkouření kotle a úpravy komína", "Regulace (termostaty, ekvitermní řízení)"], "tip": "Topení se nejlépe mění mimo topnou sezónu. Poptávku zadejte s předstihem – na podzim mají topenáři nejvíc práce.", "faq": [{"q": "Kdo uvede kotel do provozu?", "a": "Obvykle servisní technik oprávněný výrobcem kotle. Zeptejte se, jestli to topenář zajistí, nebo s kým spolupracuje."}, {"q": "Potřebuji projekt?", "a": "U výměny kotle za podobný často ne, u nové soustavy nebo změny zdroje tepla se projekt vyplatí. Topenář vám poradí."}], "sort": 2}, {"slug": "plynar", "name": "Plynař", "category": "instalace", "meta_title": "Plynař – rozvody plynu a revize, poptávka zdarma", "meta_description": "Plynař na rozvody plynu, připojení sporáku nebo kotle a opravy netěsností. Poptávka zdarma, ozvou se řemeslníci s ověřeným IČO.", "intro": "Práce na plynu patří jen do rukou odborníka s oprávněním. Plynař vybuduje nebo upraví plynovou přípojku a rozvody, připojí spotřebiče a odstraní netěsnosti. Revizi plynového zařízení smí udělat jen revizní technik s platným osvědčením. V poptávce popište, o jaký spotřebič nebo úsek rozvodu jde a jestli máte předchozí revizní zprávu.", "services": ["Nové rozvody plynu a jejich úpravy", "Připojení plynového sporáku, varné desky a kotle", "Hledání a oprava netěsností", "Tlakové zkoušky rozvodů", "Zajištění revize plynového zařízení", "Odpojení a zaslepení nepoužívaných spotřebičů"], "price_factors": ["Délka a vedení rozvodu", "Materiál potrubí", "Počet připojovaných spotřebičů", "Nutnost revize a tlakové zkoušky", "Přístupnost rozvodů"], "tip": "Cítíte plyn? Zavřete hlavní uzávěr, nepoužívejte elektrické spínače a volejte pohotovostní linku distributora plynu. Poptávka je pro plánované práce.", "faq": [{"q": "Jak často je potřeba revize?", "a": "Lhůty určují předpisy a výrobce spotřebiče. Revizní technik vám termín další revize uvede ve zprávě."}, {"q": "Může plynař udělat i revizi?", "a": "Jen pokud je zároveň revizním technikem s platným osvědčením. Zeptejte se ho na to v odpovědi na poptávku."}], "sort": 3}, {"slug": "elektrikar", "name": "Elektrikář", "category": "elektro", "meta_title": "Elektrikář – elektroinstalace a revize, poptávka zdarma", "meta_description": "Elektrikář na novou elektroinstalaci, výměnu rozvaděče, zásuvky, osvětlení nebo revizi. Zadejte poptávku zdarma, ozvou se firmy s ověřeným IČO.", "intro": "Elektrikář zapojí, opraví a zkontroluje elektroinstalaci v bytě, domě i firmě. Stará hliníková instalace, vypadávající jistič nebo plánovaná rekonstrukce – vždy se vyplatí odborník s oprávněním. Revizi smí provést jen revizní technik s platným osvědčením. Do poptávky napište stáří instalace, rozsah prací a jestli potřebujete revizní zprávu.", "services": ["Nová elektroinstalace při rekonstrukci nebo stavbě", "Výměna rozvaděče a jističů, doplnění proudového chrániče", "Montáž zásuvek, vypínačů a osvětlení", "Přípojka pro sporák, myčku nebo nabíječku elektromobilu", "Hledání a odstranění poruch", "Revize elektroinstalace (revizní technik)"], "price_factors": ["Rozsah – jednotlivé okruhy, nebo celý byt či dům", "Sekání drážek a následné zednické práce", "Počet zásuvek, světel a okruhů", "Typ rozvaděče a jisticích prvků", "Potřeba revizní zprávy"], "tip": "Při rekonstrukci bytu dělejte elektroinstalaci dřív než omítky a obklady. Pozdější úpravy vycházejí dráž.", "faq": [{"q": "Kdy potřebuji revizi?", "a": "Po nové instalaci nebo větší úpravě, při prodeji či pronájmu a pravidelně u firem. Revizní zprávu si uschovejte."}, {"q": "Musím vyměnit hliníkové vodiče?", "a": "Není to vždy povinné, ale u staré instalace se to často doporučuje. Elektrikář posoudí stav na místě."}], "sort": 4}, {"slug": "fotovoltaika", "name": "Montér fotovoltaiky", "category": "elektro", "meta_title": "Fotovoltaika – montáž solárních panelů, poptávka zdarma", "meta_description": "Montáž fotovoltaiky na rodinný dům nebo firmu: panely, střídač, baterie. Zadejte poptávku zdarma a porovnejte nabídky firem s ověřeným IČO.", "intro": "Fotovoltaická elektrárna snižuje účty za elektřinu, pokud je správně navržená na vaši spotřebu. Montážní firma posoudí střechu, navrhne výkon, střídač a případně baterii a postará se o zapojení. Připojení k distribuční soustavě schvaluje distributor. Do poptávky uveďte roční spotřebu elektřiny, typ a orientaci střechy a jestli chcete baterii.", "services": ["Návrh výkonu podle vaší spotřeby", "Montáž panelů na šikmou i plochou střechu", "Střídač a bateriové úložiště", "Zapojení do domácí instalace a revize", "Vyřízení připojení u distributora", "Rozšíření stávající elektrárny"], "price_factors": ["Výkon elektrárny a počet panelů", "Typ a stav střechy, nosná konstrukce", "Baterie a její kapacita", "Délka kabelových tras a umístění střídače", "Administrativa a případná žádost o dotaci"], "tip": "Před montáží zkontrolujte stav střechy. Pokud ji budete za pár let opravovat, udělejte to raději před instalací panelů.", "faq": [{"q": "Vyplatí se baterie?", "a": "Záleží na tom, kolik elektřiny spotřebujete přes den a večer. Chtějte od firmy výpočet pro obě varianty."}, {"q": "Pomůže firma s dotací?", "a": "Některé firmy žádost o dotaci zajišťují. Podmínky programů se mění, proto si je ověřte aktuálně."}], "sort": 5}, {"slug": "pokryvac", "name": "Pokrývač", "category": "strechy", "meta_title": "Pokrývač – střechy a klempířství, poptávka zdarma", "meta_description": "Pokrývač na novou střechu, výměnu krytiny nebo opravu zatékání. Zadejte poptávku zdarma a bez registrace, ozvou se firmy s ověřeným IČO.", "intro": "Pokrývač pokládá a opravuje střešní krytinu – pálenou i betonovou tašku, plech, šindel či lepenku. Postará se o latě, fólie, větrání střechy a ve spolupráci s klempířem i o oplechování. Při zatékání pomůže najít příčinu, než se poškodí krov. V poptávce uveďte typ a sklon střechy, přibližnou plochu v m² a co je potřeba.", "services": ["Pokládka nové krytiny", "Výměna staré krytiny včetně latí a fólie", "Opravy zatékání a poškozených tašek", "Střešní okna a výlezy", "Hřebeny, nároží a úžlabí", "Prohlídka střechy před koupí domu nebo po bouřce"], "price_factors": ["Plocha střechy v m² a její členitost", "Typ krytiny", "Sklon a výška – lešení nebo plošina", "Stav krovu a latí", "Odvoz a likvidace staré krytiny"], "tip": "Plochu střechy najdete v projektové dokumentaci. Pokud ji nemáte, uveďte půdorys domu a tvar střechy – pokrývač plochu dopočítá.", "faq": [{"q": "Kdy je nejlepší měnit střechu?", "a": "Od jara do podzimu, kdy nemrzne a méně prší. Termíny se plní brzy, poptávku zadejte s předstihem."}, {"q": "Potřebuji stavební povolení?", "a": "Výměna krytiny za podobnou ho většinou nepotřebuje, změna tvaru nebo výšky střechy ano. Ověřte si to na stavebním úřadě."}], "sort": 6}, {"slug": "klempir", "name": "Klempíř", "category": "strechy", "meta_title": "Klempíř – okapy a oplechování, poptávka zdarma", "meta_description": "Klempíř na okapy, svody, oplechování komínů, atik a parapetů. Poptávka zdarma a bez registrace, ozvou se firmy s ověřeným IČO.", "intro": "Klempíř zpracovává plech – okapy a svody, oplechování komínů, střešních prostupů, atik, říms a venkovních parapetů. Správně udělané klempířské prvky odvedou vodu od fasády a základů a prodlouží život střechy. Uveďte v poptávce délku okapů v metrech, materiál (pozink, titanzinek, měď, poplastovaný plech) a výšku domu.", "services": ["Montáž a výměna okapů a svodů", "Oplechování komínů a střešních prostupů", "Oplechování atik, říms a zdí", "Venkovní parapety", "Opravy netěsných spojů a žlabů", "Lapače listí a sněhové zábrany"], "price_factors": ["Délka žlabů a svodů v metrech", "Materiál plechu", "Výška domu – lešení nebo plošina", "Počet komínů a prostupů", "Demontáž a odvoz starých prvků"], "tip": "Zatéká kolem komína? Často jde o oplechování, ne o krytinu. Napište to do poptávky – klempíř si vezme správný materiál.", "faq": [{"q": "Jaký plech vybrat?", "a": "Pozink je nejlevnější, titanzinek a měď vydrží déle. Poplastovaný plech dostanete v barvě střechy."}, {"q": "Dělá klempíř i krytinu?", "a": "Někteří klempíři jsou zároveň pokrývači. Pokud potřebujete obojí, napište to do poptávky."}], "sort": 7}, {"slug": "tesar", "name": "Tesař", "category": "tesarske", "meta_title": "Tesař – krovy a dřevěné konstrukce, poptávka zdarma", "meta_description": "Tesař na krov, pergolu, přístřešek, dřevostavbu nebo opravu trámů. Zadejte poptávku zdarma, ozvou se firmy s ověřeným IČO.", "intro": "Tesař staví a opravuje dřevěné nosné konstrukce – krovy, stropy, pergoly, přístřešky na auto, terasy i dřevostavby. Při rekonstrukci střechy posoudí stav trámů a vymění napadené nebo shnilé prvky. Do poptávky napište rozměry, účel stavby a jestli máte projekt nebo statický výpočet.", "services": ["Nový krov a jeho úpravy", "Výměna a zesílení poškozených trámů", "Pergoly, altány a přístřešky na auto", "Dřevěné terasy a podlahy na terasu", "Dřevěné stropy a podkroví", "Ošetření dřeva proti škůdcům a hnilobě"], "price_factors": ["Rozměry a složitost konstrukce", "Druh a jakost dřeva", "Potřeba projektu nebo statika", "Doprava a jeřáb", "Stav stávající konstrukce"], "tip": "U pergoly nebo přístřešku si předem ověřte, jestli stavba nepotřebuje ohlášení stavebnímu úřadu.", "faq": [{"q": "Dodá tesař i krytinu?", "a": "Některé firmy dělají krov i krytinu. Jinak se domluvte s pokrývačem, aby na sebe práce navazovaly."}, {"q": "Jaké dřevo vybrat?", "a": "Pro konstrukce se nejčastěji používá smrk, venku často modřín nebo tepelně upravené dřevo. Tesař doporučí podle účelu."}], "sort": 8}, {"slug": "truhlar", "name": "Truhlář", "category": "tesarske", "meta_title": "Truhlář – nábytek na míru, poptávka zdarma", "meta_description": "Truhlář na kuchyň, vestavěné skříně, schody, dveře nebo nábytek na míru. Poptávka zdarma a bez registrace, ozvou se firmy s ověřeným IČO.", "intro": "Truhlář vyrobí nábytek přesně do vašeho prostoru – kuchyňskou linku, vestavěnou skříň, knihovnu, schodiště nebo interiérové dveře. Opravuje i starší dřevěné prvky. Do poptávky přidejte rozměry, materiál (masiv, dýha, lamino), představu o vzhledu a ideálně náčrt nebo fotku prostoru.", "services": ["Kuchyňské linky na míru", "Vestavěné skříně a šatny", "Dřevěná schodiště a zábradlí", "Interiérové dveře a zárubně", "Renovace a opravy nábytku", "Obklady stěn a stropů ze dřeva"], "price_factors": ["Materiál – masiv, dýha, lamino, MDF", "Kování a spotřebiče", "Rozměry a složitost tvarů", "Povrchová úprava", "Doprava a montáž"], "tip": "Prostor zaměřte až po hotových podlahách a obkladech, nebo si nechte zaměřit truhlářem – ušetříte si nepříjemná překvapení.", "faq": [{"q": "Jak dlouho výroba trvá?", "a": "Záleží na vytížení dílny a složitosti. Termín si nechte potvrdit v nabídce nebo ve smlouvě o dílo."}, {"q": "Mám chtít návrh?", "a": "Ano, ideálně nákres s rozměry. Předejdete nedorozumění o vzhledu i ceně."}], "sort": 9}, {"slug": "zednik", "name": "Zedník", "category": "zednicke", "meta_title": "Zedník – rekonstrukce a zednické práce, poptávka zdarma", "meta_description": "Zedník na zdění, omítky, příčky, bourání a drobné stavební úpravy. Zadejte poptávku zdarma, ozvou se firmy s ověřeným IČO.", "intro": "Zedník zvládne většinu stavebních prací – zdění a bourání příček, omítky, betonování, zednické začištění po instalatérech a elektrikářích i drobné opravy. Často koordinuje rekonstrukci jako celek. Do poptávky napište rozsah v m² nebo bm, stáří domu a jestli jde o nosné konstrukce.", "services": ["Zdění a bourání příček", "Vnitřní a venkovní omítky", "Betonování základů a podlah", "Zednické začištění po instalacích", "Opravy prasklin a vlhkého zdiva", "Drobné stavební úpravy a vybourání otvorů"], "price_factors": ["Rozsah v m² a druh práce", "Zásahy do nosných konstrukcí a statika", "Odvoz suti a kontejner", "Materiál", "Přístupnost – patro, výtah, parkování"], "tip": "Bourání nosné zdi nebo vybourání otvoru vždy konzultujte se statikem. Zedník vám obvykle doporučí, s kým spolupracuje.", "faq": [{"q": "Kdo zajistí kontejner na suť?", "a": "Domluvte se v nabídce. Odvoz suti bývá samostatná položka."}, {"q": "Potřebuji ohlásit stavbu?", "a": "U zásahu do nosných konstrukcí většinou ano. Informujte se na stavebním úřadě nebo u statika."}], "sort": 10}, {"slug": "sadrokartonar", "name": "Sádrokartonář", "category": "zednicke", "meta_title": "Sádrokartonář – podhledy a příčky, poptávka zdarma", "meta_description": "Sádrokartonář na podhledy, příčky, předstěny a podkroví. Poptávka zdarma a bez registrace, ozvou se firmy s ověřeným IČO.", "intro": "Sádrokarton je rychlá a čistá cesta k novým příčkám, sníženým stropům, předstěnám pro instalace i k obytnému podkroví. Sádrokartonář namontuje konstrukci, desky, izolaci a připraví povrch pro malíře. V poptávce uveďte plochu v m², výšku stropu a jestli jde o koupelnu (impregnované desky) nebo podkroví.", "services": ["Podhledy a snížené stropy", "Příčky s izolací proti hluku", "Předstěny pro WC a instalace", "Obklad podkroví a půdní vestavby", "Protipožární konstrukce", "Tmelení a příprava pro malování"], "price_factors": ["Plocha v m²", "Typ desek – standardní, impregnované, protipožární", "Izolace a akustika", "Výška a tvary (oblouky, římsy)", "Kvalita tmelení"], "tip": "Myslete dopředu na zavěšené skříňky a televizi – do příčky se dávají výztuhy ještě před zaklopením.", "faq": [{"q": "Je sádrokarton do koupelny?", "a": "Ano, impregnované desky do vlhkého prostředí. V místě sprchy se navíc dělá hydroizolace."}, {"q": "Jak rychle je hotovo?", "a": "Příčka nebo podhled bývá hotový za pár dní včetně tmelení. Přesný termín uvede řemeslník."}], "sort": 11}, {"slug": "rekonstrukce-bytu", "name": "Rekonstrukce bytu a koupelny", "category": "zednicke", "meta_title": "Rekonstrukce bytu a koupelny – poptávka zdarma", "meta_description": "Kompletní rekonstrukce bytu, koupelny nebo kuchyně na klíč. Zadejte poptávku zdarma a porovnejte nabídky firem s ověřeným IČO.", "intro": "Rekonstrukce bytu nebo koupelny spojuje více řemesel – bourání, instalace, elektro, omítky, obklady, podlahy a malování. Firma na klíč je zkoordinuje a za výsledek odpovídá jako celek. V poptávce popište rozsah (jen koupelna, nebo celý byt), plochu, stáří domu a termín, kdy se můžete vystěhovat.", "services": ["Koupelna a WC na klíč", "Kompletní rekonstrukce bytu", "Výměna bytového jádra", "Nové rozvody vody, odpadů a elektřiny", "Podlahy, obklady a malování", "Koordinace řemesel a úklid po stavbě"], "price_factors": ["Rozsah a plocha", "Zásahy do instalací a nosných konstrukcí", "Standard materiálů a vybavení", "Pravidla domu – hlučné práce, výtah, skládka", "Délka rekonstrukce a koordinace řemesel"], "tip": "Před začátkem informujte správce domu a sousedy. Mnohé domy mají pravidla pro hlučné práce a odvoz suti.", "faq": [{"q": "Mám chtít smlouvu o dílo?", "a": "Určitě. Má obsahovat rozsah, cenu, termín, platby a záruku. Usnadní řešení případných sporů."}, {"q": "Jak se platí?", "a": "Obvykle záloha a doplatek po předání. Velké zálohy předem bez smlouvy nedoporučujeme."}], "sort": 12}, {"slug": "malir", "name": "Malíř pokojů", "category": "malovani", "meta_title": "Malíř pokojů – výmalba bytu, poptávka zdarma", "meta_description": "Malíř na výmalbu bytu, domu nebo kanceláře, včetně oprav omítek a stěrek. Poptávka zdarma a bez registrace, ozvou se firmy s ověřeným IČO.", "intro": "Malíř pokojů připraví povrch, opraví praskliny, zakryje podlahy a nábytek a stěny i stropy vymaluje. Kvalitní příprava je polovina výsledku. Do poptávky napište plochu v m² (nebo počet a velikost místností), výšku stropů a jestli se byt maluje vystěhovaný.", "services": ["Výmalba bytů, domů a kanceláří", "Penetrace a opravy prasklin", "Stěrky a hlazení stěn", "Barevné malby a dekorativní techniky", "Malování po rekonstrukci", "Odstranění plísní a protiplísňové nátěry"], "price_factors": ["Plocha stěn a stropů v m²", "Stav podkladu a rozsah oprav", "Počet vrstev a barevnost", "Vystěhovaný, nebo zařízený byt", "Kvalita barvy"], "tip": "Pokud chcete barevné stěny, napište to do poptávky – sytější odstíny často potřebují víc vrstev.", "faq": [{"q": "Kdo kupuje barvu?", "a": "Domluvte se. Malíř obvykle doporučí ověřenou barvu a nakoupí ji, v nabídce ale chtějte materiál zvlášť."}, {"q": "Jak dlouho výmalba trvá?", "a": "Byt 2+1 bývá hotový za pár dní, podle oprav a schnutí. Termín si nechte potvrdit."}], "sort": 13}, {"slug": "naterac", "name": "Natěrač", "category": "malovani", "meta_title": "Natěrač – nátěry fasád, oken a plotů, poptávka zdarma", "meta_description": "Natěrač na nátěry oken, dveří, plotů, střech, fasád a kovových konstrukcí. Zadejte poptávku zdarma, ozvou se firmy s ověřeným IČO.", "intro": "Natěrač chrání a obnovuje dřevo, kov i omítky – okna, dveře, ploty, brány, plechové střechy, fasády a zábradlí. Nejdůležitější je příprava: odstranění starých vrstev, odrezení a správný základ. Do poptávky uveďte, co se natírá, přibližnou plochu nebo délku a materiál.", "services": ["Nátěry dřevěných oken a dveří", "Nátěry plotů a bran", "Nátěry plechových střech", "Fasádní nátěry", "Odrezení a nátěry kovových konstrukcí", "Lazury a oleje na dřevo"], "price_factors": ["Plocha a členitost natíraných prvků", "Stav – loupající se barva, rez", "Druh nátěrového systému", "Výška a přístup", "Počet vrstev"], "tip": "Venkovní nátěry se dělají za sucha a při teplotách doporučených výrobcem barvy. Počítejte s tím při plánování termínu.", "faq": [{"q": "Jak často natírat?", "a": "Záleží na materiálu a slunci. Dřevo na jižní straně potřebuje péči častěji."}, {"q": "Je nutné staré nátěry odstranit?", "a": "Co se odlupuje, ano. Pevný starý nátěr často stačí přebrousit. Natěrač to posoudí."}], "sort": 14}, {"slug": "fasadnik", "name": "Fasádník", "category": "fasady", "meta_title": "Fasádník – fasády a zateplení, poptávka zdarma", "meta_description": "Fasádník na zateplení domu, novou fasádu, omítky a opravy. Poptávka zdarma a bez registrace, ozvou se firmy s ověřeným IČO.", "intro": "Fasádník zateplí dům kontaktním zateplovacím systémem, opraví nebo udělá novou omítku a postará se o detaily kolem oken, soklu a parapetů. Dobře provedené zateplení snižuje náklady na vytápění. Do poptávky napište plochu fasády v m², tloušťku a druh izolantu (pokud ho znáte) a výšku domu.", "services": ["Zateplení fasády polystyrenem nebo minerální vlnou", "Nové fasádní omítky", "Opravy a sanace starých fasád", "Zateplení a úprava soklu", "Fasádní nátěry", "Montáž lešení"], "price_factors": ["Plocha fasády v m²", "Druh a tloušťka izolantu", "Lešení a výška domu", "Členitost – okna, balkony, rohy", "Stav podkladu"], "tip": "U zateplení se vyplatí hlídat detaily kolem oken a parapetů. Chtějte, aby nabídka uváděla použitý systém a tloušťku izolantu.", "faq": [{"q": "Kdy se zatepluje?", "a": "Za vhodných teplot podle technického listu systému, obvykle od jara do podzimu."}, {"q": "Potřebuji povolení?", "a": "Záleží na stavbě a lokalitě. Informujte se na stavebním úřadě, případně v SVJ."}], "sort": 15}, {"slug": "obkladac", "name": "Obkladač", "category": "obklady", "meta_title": "Obkladač – obklady a dlažby, poptávka zdarma", "meta_description": "Obkladač na koupelny, kuchyně, terasy a velkoformátové dlažby. Zadejte poptávku zdarma, ozvou se firmy s ověřeným IČO.", "intro": "Obkladač položí obklady a dlažby v koupelně, kuchyni, chodbě i na terase. Postará se o vyrovnání podkladu, hydroizolaci ve sprše a precizní spárování. Do poptávky uveďte plochu v m², formát obkladu (velké formáty jsou pracnější) a jestli je potřeba odstranit starý obklad.", "services": ["Obklady a dlažby v koupelně a WC", "Kuchyňské zástěny", "Velkoformátové dlažby", "Dlažby na terasách a balkonech", "Hydroizolace sprchových koutů", "Opravy a přespárování"], "price_factors": ["Plocha v m²", "Formát a druh obkladu", "Stav podkladu a vyrovnání", "Bourání starého obkladu", "Lišty, rohy a řezání"], "tip": "Kupte obklad s rezervou kolem 10 % a ze stejné šarže – na pozdější opravy se hodí.", "faq": [{"q": "Kdo dodá obklad?", "a": "Obvykle si ho vybíráte sami. Lepidla, hydroizolaci a spárovací hmotu často zajistí obkladač."}, {"q": "Kdy se může do sprchy?", "a": "Až po vytvrdnutí lepidel a spárovací hmoty podle výrobce. Obkladač vám řekne přesnou dobu."}], "sort": 16}, {"slug": "podlahar", "name": "Podlahář", "category": "podlahy", "meta_title": "Podlahář – pokládka a renovace podlah, poptávka zdarma", "meta_description": "Podlahář na pokládku vinylu, laminátu, dřevěných podlah a broušení parket. Poptávka zdarma a bez registrace, ozvou se firmy s ověřeným IČO.", "intro": "Podlahář připraví podklad, položí novou podlahu a dokončí lišty a přechody. Umí i renovaci – broušení a lakování parket nebo olejování dřeva. Do poptávky napište plochu v m², druh podlahy a stav podkladu (beton, anhydrit, stará krytina).", "services": ["Pokládka vinylu, laminátu a dřevěných podlah", "Broušení a lakování parket", "Vyrovnání a stěrkování podkladu", "Koberce a PVC", "Lišty a přechodové profily", "Opravy poškozených podlah"], "price_factors": ["Plocha v m²", "Druh podlahy a způsob pokládky", "Stav a rovinnost podkladu", "Odstranění staré krytiny", "Množství lišt a přechodů"], "tip": "Před pokládkou musí být podklad suchý. U nových potěrů změřte vlhkost – podlahář to obvykle udělá.", "faq": [{"q": "Plovoucí, nebo lepená podlaha?", "a": "Lepená je