/** Administrace: všechny profese včetně skrytých. */
create or replace function public.admin_professions() returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare r jsonb;
begin
  perform app.require_admin();
  select coalesce(jsonb_agg(to_jsonb(p) order by p.sort, p.name), '[]'::jsonb) into r from public.professions p;
  return r;
end $$;

/**
 * Uložení profese (nová i úprava). p_original = původní adresa při přejmenování adresy, jinak null.
 * Seznamy (služby, cena) se posílají jako pole textů, otázky jako pole {q, a}.
 */
create or replace function public.admin_save_profession(p jsonb, p_original text default null) returns text
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_slug text := lower(trim(coalesce(p ->> 'slug', '')));
  v_list text[];
  v_list2 text[];
  v_faq jsonb;
begin
  perform app.require_admin();
  select coalesce(array_agg(trim(x)) filter (where trim(x) <> ''), '{}') into v_list from jsonb_array_elements_text(coalesce(p -> 'services', '[]')) x;
  select coalesce(array_agg(trim(x)) filter (where trim(x) <> ''), '{}') into v_list2 from jsonb_array_elements_text(coalesce(p -> 'price_factors', '[]')) x;
  select coalesce(jsonb_agg(jsonb_build_object('q', trim(f ->> 'q'), 'a', trim(f ->> 'a'))) filter (where trim(coalesce(f ->> 'q', '')) <> '' and trim(coalesce(f ->> 'a', '')) <> ''), '[]')
    into v_faq from jsonb_array_elements(coalesce(p -> 'faq', '[]')) f;
  if p_original is not null and p_original <> v_slug then
    update public.professions set slug = v_slug where slug = p_original;
  end if;
  insert into public.professions (slug, name, category, meta_title, meta_description, intro, services, price_factors, tip, faq, published, sort, updated_at)
  values (v_slug, trim(p ->> 'name'), p ->> 'category', trim(p ->> 'meta_title'), trim(p ->> 'meta_description'), trim(p ->> 'intro'),
          v_list, v_list2, nullif(trim(coalesce(p ->> 'tip', '')), ''), v_faq, coalesce((p ->> 'published')::boolean, true),
          coalesce(nullif(p ->> 'sort', '')::int, 100), now())
  on conflict (slug) do update set name = excluded.name, category = excluded.category, meta_title = excluded.meta_title,
    meta_description = excluded.meta_description, intro = excluded.intro, services = excluded.services,
    price_factors = excluded.price_factors, tip = excluded.tip, faq = excluded.faq, published = excluded.published,
    sort = excluded.sort, updated_at = now();
  perform app.log_admin('profession_save', null, null, jsonb_build_object('slug', v_slug));
  return v_slug;
end $$;

create or replace function public.admin_delete_profession(p_slug text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  perform app.require_admin();
  delete from public.professions where slug = p_slug;
  perform app.log_admin('profession_delete', null, null, jsonb_build_object('slug', p_slug));
end $$;

revoke all on function public.admin_professions(), public.admin_save_profession(jsonb, text), public.admin_delete_profession(text) from public, anon;
grant execute on function public.admin_professions(), public.admin_save_profession(jsonb, text), public.admin_delete_profession(text) to authenticated;
